def main():
    base = Path(__file__).resolve().parent
    if not (base / "main.py").exists():
        print("X  main.py nicht gefunden. Skript in den DS4-Ordner legen!")
        return 1
    print("=" * 60)
    print(" CORRIDOR SLAYER - PAKET 5: MOBILE EDITION")
    print("=" * 60)
    for name in FILES:
        src = base / name
        if src.exists():
            bak = base / (src.stem + "_backup_paket5.py")
            if not bak.exists():
                shutil.copy2(src, bak)
                print(f"  Backup: {bak.name}")
            else:
                print(f"  Backup existiert bereits: {bak.name}")
    for name, chunks in FILES.items():
        raw = base64.b64decode("".join(chunks))
        (base / name).write_bytes(raw)
        py_compile.compile(str(base / name), doraise=True)
        print(f"  OK: {name} installiert ({len(raw)} Bytes, kompiliert)")
    print()
    print("Fertig!  Starten:   py main.py")
    print("Handy (Pydroid 3): Projektordner oeffnen und main.py starten.")
    print("Tastatur bleibt optional: ESC=Pause  M=Sound  Q=Uebertaktung.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
